import itertools

def solve_for_n(n, max_m=20):
    for m in range(1, max_m + 1):
        m2 = m*m
        seven_m2 = 7 * m2

        # Find all combinations of a_i such that sum(a_i^2) = m2
        # To optimize, we can search for a_i in range(-m, m+1)
        a_vals = []
        for a in itertools.product(range(-m, m + 1), repeat=n):
            if sum(x*x for x in a) == m2:
                a_vals.append(a)

        if not a_vals:
            continue

        # Find all combinations of b_i such that sum(b_i^2) = seven_m2
        # b_i can be in range(-int(seven_m2**0.5), int(seven_m2**0.5) + 1)
        b_limit = int(seven_m2**0.5)
        b_vals = []
        for b in itertools.product(range(-b_limit, b_limit + 1), repeat=n):
            if sum(x*x for x in b) == seven_m2:
                b_vals.append(b)

        if not b_vals:
            continue

        # Check if any (a, b) pair satisfies sum(a_i * b_i) = 0
        for a in a_vals:
            for b in b_vals:
                if sum(ai * bi for ai, bi in zip(a, b)) == 0:
                    return True, m, a, b
    return False, None, None, None

for n in [3, 4, 5]:
    res, m, a, b = solve_for_n(n)
    print(f"n={n}: {res}, m={m}, a={a}, b={b}")

