def find_orthogonal_with_ratio(n, ratio):
    # We want |a|^2 = ratio * |b|^2 and a . b = 0
    # Search for b, then check for a.
    for b_limit in range(1, 10):
        for b in itertools.product(range(-b_limit, b_limit + 1), repeat=n):
            b_sq = sum(bi*bi for bi in b)
            if b_sq == 0: continue

            target_a_sq = ratio * b_sq
            if target_a_sq % 1 != 0: continue
            target_a_sq = int(target_a_sq)

            # Now we need a such that |a|^2 = target_a_sq and a . b = 0
            # Search for a
            a_limit = int(target_a_sq**0.5)
            for a in itertools.product(range(-a_limit, a_limit + 1), repeat=n):
                if sum(ai*ai for ai in a) == target_a_sq:
                    if sum(ai*bi for ai, bi in zip(a, b)) == 0:
                        return True, a, b
    return False, None, None

