def get_vectors_with_norm_sq(n, target_sq):
    import itertools
    results = []
    limit = int(target_sq**0.5)
    # This is still a bit slow, but better.
    # Let's use a recursive function.
    def find_comb(curr_n, curr_sq, curr_vec):
        if curr_n == 0:
            if curr_sq == 0:
                results.append(tuple(curr_vec))
            return

        # Optimization: the remaining elements must be able to sum to curr_sq
        # Each element xi^2 <= curr_sq
        max_xi = int(curr_sq**0.5)
        for xi in range(-max_xi, max_xi + 1):
            find_comb(curr_n - 1, curr_sq - xi*xi, curr_vec + [xi])

    find_comb(n, target_sq, [])
    return results

