def find_a_b_for_n(n, max_m=20):
    for m in range(1, max_m + 1):
        m2 = m*m
        target_b_sq = 7 * m2

        # Find all a such that sum(ai^2) = m2
        a_vecs = []
        def find_vec(curr_n, curr_sq, curr_vec, res_list):
            if curr_n == 1:
                if curr_sq >= 0 and int(curr_sq**0.5)**2 == curr_sq:
                    root = int(curr_sq**0.5)
                    res_list.append(tuple(curr_vec + [root]))
                    if root != 0:
                        res_list.append(tuple(curr_vec + [-root]))
                return
            max_val = int(curr_sq**0.5)
            for val in range(-max_val, max_val + 1):
                find_vec(curr_n - 1, curr_sq - val*val, curr_vec + [val], res_list)

        find_vec(n, m2, [], a_vecs)

        # For each a, search for b such that sum(bi^2) = target_b_sq and a.b = 0
        for a in a_vecs:
            # To find b, we can search b_i in range(-int(target_b_sq**0.5), ...)
            # But we can also use the a.b = 0 condition to solve for one b_i
            b_limit = int(target_b_sq**0.5)

            # Let's use a simpler search for b
            def find_b(curr_n, curr_sq, curr_dot, curr_vec):
                if curr_n == 1:
                    # b_n must satisfy:
                    # 1. b_n^2 = curr_sq
                    # 2. a_n * b_n = -curr_dot
                    if curr_sq < 0: return False
                    root = int(curr_sq**0.5)
                    if root*root == curr_sq:
                        for b_n in [root, -root]:
                            if a[n-1] * b_n == -curr_dot:
                                return True
                    return False

                max_val = int(curr_sq**0.5)
                for val in range(-max_val, max_val + 1):
                    if find_b(curr_n - 1, curr_sq - val*val, curr_dot + a[n-curr_n]*val, curr_vec + [val]):
                        return True
                return False

            if find_b(n, target_b_sq, 0, []):
                return True, m, a
    return False, None, None

